use std::sync::{Arc, Mutex};
use std::thread;

fn main() {
    // Shared resources: a (lock), b (lock)
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

    // R1: main task starts one outer worker [U]
    let outer_handle = {
        let a = Arc::clone(&a);
        let b = Arc::clone(&b);
        thread::spawn(move || {
            // R2: outer starts a nested group of two inner tasks [U]
            let mut inner_handles = Vec::new();

            for name in ["x1", "x2"] {
                let a = Arc::clone(&a);
                let b = Arc::clone(&b);
                inner_handles.push(thread::spawn(move || {
                    // R4: both inner tasks take the mutexes in the same
                    // order (a, then b), so no wait cycle can form.
                    let _ga = a.lock().unwrap();
                    // Small yield point to allow interleaving; ordering
                    // of acquisition is still a-then-b for both tasks.
                    thread::yield_now();
                    let _gb = b.lock().unwrap();

                    // R3: at this point the inner task holds both a and b.
                    let _ = name;
                    thread::yield_now();

                    // Locks released here when guards drop.
                }));
            }

            // R5: outer completes only after both inner tasks finish.
            for h in inner_handles {
                h.join().unwrap();
            }
        })
    };

    // R5/R6: wait for outer; every interleaving terminates because
    // lock acquisition order is consistent (a before b) for x1 and x2.
    outer_handle.join().unwrap();

    // R7: print exactly the required line, then exit [U]
    println!("DONE done=1");
}
```

**How the requirements are met:**

- **R1 [U]:** `main` spawns a single thread playing the role of `outer`.
- **R2 [U]:** `outer` spawns two threads, `x1` and `x2`, as a nested group.
- **R3:** Each inner task acquires `_ga` (mutex `a`) and `_gb` (mutex `b`); while both guards are alive, the task holds both mutexes simultaneously.
- **R4:** Both inner tasks acquire in the identical order — `a` then `b` — so the resource-allocation graph is acyclic and no deadlock cycle can form.
- **R5:** `outer` joins both inner handles before returning; `main` joins `outer` before printing.
- **R6:** Since lock order is uniform and all joins are unconditional, every schedule terminates.
- **R7 [U]:** The program prints exactly `DONE done=1` and exits.
